import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code for fused Linear + Mish + Mish
fusion_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float mish(const float x) {
    // mish(x) = x * tanh(softplus(x)), softplus(x) = log(1 + exp(x))
    float sp = log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void linear_mish_mish_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    const int B, 
    const int in_features, 
    const int out_features
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * out_features) return;

    int row = idx / out_features;
    int col = idx % out_features;

    float val = 0.0f;
    for (int k = 0; k < in_features; k++) {
        val += x[row * in_features + k] * w[k * out_features + col];
    }
    val += b[col];
    val = mish(mish(val));
    out[row * out_features + col] = val;
}

torch::Tensor linear_mish_mish_cuda(
    torch::Tensor x, 
    torch::Tensor w, 
    torch::Tensor b
) {
    // Ensure contiguous memory
    x = x.contiguous();
    w = w.contiguous();
    b = b.contiguous();

    const int B = x.size(0);
    const int in_features = x.size(1);
    const int out_features = w.size(1);

    auto out = torch::empty({B, out_features}, x.options());

    const int threads = 256;
    const int blocks = (B * out_features + threads - 1) / threads;

    linear_mish_mish_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        in_features,
        out_features
    );

    return out;
}
"""

fusion_header = r"""
torch::Tensor linear_mish_mish_cuda(
    torch::Tensor x, 
    torch::Tensor w, 
    torch::Tensor b
);
"""

fusion_ext = load_inline(
    name="fusion_ext",
    cpp_sources=fusion_header,
    cuda_sources=fusion_source,
    functions=["linear_mish_mish_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Fused model that performs a matrix multiplication and two Mish activations in one custom CUDA kernel.
    """
    def __init__(self, in_features, out_features):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(in_features, out_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fusion_ext.linear_mish_mish_cuda(x, self.weight, self.bias)

def get_inputs():
    batch_size = 128
    in_features = 10
    return [torch.randn(batch_size, in_features)]

def get_init_inputs():
    in_features = 10
    out_features = 20
    return [in_features, out_features]
